using System;
using System.IO;
using System.Drawing;
using System.Collections.Generic;
using System.Reflection;
using System.Diagnostics;
using System.Windows.Forms;
using EanEtikety;
class Revision22Tests {
 static string dir;static void Check(bool b,string m){if(!b)throw new Exception(m);}static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(o);}static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,BindingFlags.NonPublic|BindingFlags.Instance).Invoke(o,args);}
 static AiValue AI(string code,string value){return new AiValue{AI=code,Data=value};}static void Bad(params AiValue[] items){bool failed=false;try{Gs1.Payload(new List<AiValue>(items));}catch{failed=true;}Check(failed,"Invalid GS1 was accepted");}
 static void Snap(Form f,string name){using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(Path.Combine(dir,name+".png"));}}
 static T Find<T>(Control c) where T:Control{foreach(Control child in c.Controls){if(child is T)return (T)child;var result=Find<T>(child);if(result!=null)return result;}return null;}
 static T Named<T>(Control c,string name) where T:Control{if(c is T&&c.Name==name)return (T)c;foreach(Control child in c.Controls){var found=Named<T>(child,name);if(found!=null)return found;}return null;}
 static Button Button(Control c,string text){foreach(Control child in c.Controls){if(child is Button&&child.Text==text)return (Button)child;var result=Button(child,text);if(result!=null)return result;}return null;}
 [STAThread]static void Main(string[] args){dir=args[0];Directory.CreateDirectory(dir);try{Run();File.WriteAllText(Path.Combine(dir,"passed.txt"),"PASS: GS1 AI validation, FNC1 and HRI, XML/ZPL/PRN roundtrip, GS1 dialog ordering/data/cancel, cached drag path, final rendering, plain Code128 compatibility.");}catch(Exception e){File.WriteAllText(Path.Combine(dir,"failed.txt"),e.ToString());Environment.ExitCode=1;}}
 static void Run(){
  var cases=new[]{new List<AiValue>{AI("02","09506000134352"),AI("37","24")},new List<AiValue>{AI("01","09506000134352"),AI("10","LOT12"),AI("17","270100")},new List<AiValue>{AI("10","ABC"),AI("21","XYZ123")},new List<AiValue>{AI("37","123"),AI("02","09506000134352")},new List<AiValue>{AI("01","09506000134352"),AI("3103","001250")}};
  Check(Gs1.Payload(cases[0])=="02095060001343523724","fixed + variable payload");Check(Gs1.Payload(cases[1])=="010950600013435210LOT12\u001d17270100","FNC1 between variable and fixed");Check(Gs1.Human(cases[0])=="(02)09506000134352(37)24","HRI brackets");
  Bad(AI("01","09506000134353"));Bad(AI("02","123"));Bad(AI("37","ABC"));Bad(AI("17","270231"));Bad(AI("17","271300"));Bad(AI("10","žltý"));Bad(AI("10","A B"));Bad(AI("10",""));Bad(AI("9999","1"));Bad(AI("10","a"),AI("10","b"));Bad(AI("240",new string('A',30)),AI("241",new string('B',30)));
  var vectors=new List<string>();for(int i=0;i<cases.Length;i++){string payload=Gs1.Payload(cases[i]);var codes=MoreBarcodes.Gs1Codes(payload);Check(codes[1]==102&&codes[codes.Count-1]==106,"FNC1 leading/stop");int checksum=codes[0];for(int j=1;j<codes.Count-2;j++)checksum+=j*codes[j];Check(checksum%103==codes[codes.Count-2],"Code128 checksum");vectors.Add(Convert.ToBase64String(System.Text.Encoding.ASCII.GetBytes(payload))+"\t"+string.Join(",",codes.ConvertAll(x=>x.ToString()).ToArray())+"\t"+MoreBarcodes.Gs1Bits(payload));var s=LabelSettings.Default();s.Kind=128;s.Gs1Mode=true;s.ApplicationIdentifiers=cases[i];s.Width=140;s.Height=60;s.BarWidth=120;s.BarX=10;s.BarHeight=30;Engine.Save(Path.Combine(dir,"gs1-"+i+".ean.xml"),s);Engine.Pdf(Path.Combine(dir,"gs1-"+i+".pdf"),s);Engine.Docx(Path.Combine(dir,"gs1-"+i+".docx"),s);Engine.Zpl(Path.Combine(dir,"gs1-"+i+".zpl"),s);using(var b=Engine.Render(s))b.Save(Path.Combine(dir,"gs1-"+i+".png"));var back=Engine.Load(Path.Combine(dir,"gs1-"+i+".ean.xml"));Check(Engine.CodeBits(back)==Engine.CodeBits(s),"XML GS1 persistence");var z=ZplImport.Project(File.ReadAllText(Path.Combine(dir,"gs1-"+i+".zpl")));Check(z.Gs1Mode&&Gs1.Payload(z.ApplicationIdentifiers)==payload,"ZPL GS1 persistence");}
  File.WriteAllLines(Path.Combine(dir,"vectors.tsv"),vectors);File.Copy(Path.Combine(dir,"gs1-0.zpl"),Path.Combine(dir,"sample.prn"),true);
  var old=Engine.Load("tests/fixtures/work/qa-2.0.1/settings.ean.xml");Check(!old.Gs1Mode,"legacy defaults");var plain=LabelSettings.Default();plain.Kind=128;plain.Ean="ABC123";Check(Engine.CodeBits(plain)==MoreBarcodes.Bits("ABC123",128),"plain code128 unchanged");
  Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);using(var form=new MainForm(Path.Combine(dir,"preferences.xml"))){form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);form.Show();Application.DoEvents();Call(form,"OpenImportedFile",Path.Combine(dir,"sample.prn"));var s=(LabelSettings)Call(form,"Read");Check(s.Gs1Mode&&s.ApplicationIdentifiers[1].AI=="37","PRN editable project");Snap(form,"gs1-main");
   Exception error=null;bool shown=false;var timer=new Timer{Interval=100};timer.Tick+=delegate{timer.Stop();try{foreach(Form d in Application.OpenForms)if(d!=form){shown=true;var editor=(Gs1EditorDialog)d;Named<TextBox>(d,"gs1-data-37").Text="48";Named<Button>(d,"gs1-up-37").PerformClick();Check(editor.Values[0].AI=="37","move AI up");Snap(d,"gs1-editor");Button(d,"Použiť").PerformClick();break;}}catch(Exception e){error=e;foreach(Form d in Application.OpenForms)if(d!=form){d.Close();break;}}};timer.Start();Call(form,"EditGs1");timer.Dispose();if(error!=null)throw error;Check(shown,"GS1 dialog");s=(LabelSettings)Call(form,"Read");Check(s.ApplicationIdentifiers[0].AI=="37"&&s.ApplicationIdentifiers[0].Data=="48","AI order/data saved");
   var cancelTimer=new Timer{Interval=100};cancelTimer.Tick+=delegate{cancelTimer.Stop();foreach(Form d in Application.OpenForms)if(d!=form){Named<TextBox>(d,"gs1-data-37").Text="999";Button(d,"Zrušiť").PerformClick();break;}};cancelTimer.Start();Call(form,"EditGs1");cancelTimer.Dispose();Check(((LabelSettings)Call(form,"Read")).ApplicationIdentifiers[0].Data=="48","cancel changed GS1 data");
   var preview=(PreviewPanel)Get(form,"preview");var before=preview.Scene;var watch=Stopwatch.StartNew();for(int i=0;i<1000;i++)Call(form,"EditElement",new ElementEdit{Index=-1,X=10+i*.001,Y=10,Width=s.BarWidth,Height=Engine.BarcodeHeight(s),Font=s.DigitSize});watch.Stop();Check(object.ReferenceEquals(before,preview.Scene),"drag rebuilt cached scene");s=(LabelSettings)Call(form,"Read");Check(Math.Abs(s.BarX-10.999)<.011,"last drag coordinate");File.WriteAllText(Path.Combine(dir,"performance.txt"),"1000 drag updates with cached vector scene: "+watch.ElapsedMilliseconds+" ms");Call(form,"UpdatePreview");Check(!object.ReferenceEquals(before,preview.Scene),"final update did not rebuild");Check(preview.Scene!=null,"final scene");
   Call(form,"Apply",LabelSettings.Default());form.Close();
  }
 }
}
